SELECT c.name, c.artist_v2, c.isPromo
FROM cards c
JOIN (
  SELECT uuid
  FROM rulings
  GROUP BY uuid
  HAVING COUNT(*) = (
    SELECT MAX(cnt) FROM (SELECT COUNT(*) AS cnt FROM rulings GROUP BY uuid)
  )
) r ON c.uuid = r.uuid;

SELECT DISTINCT c.name, c.artist_v2, c.isPromo
FROM cards c
JOIN (
  SELECT uuid, COUNT(*) AS rulings_count
  FROM rulings
  GROUP BY uuid
) rc ON c.uuid = rc.uuid
WHERE rc.rulings_count = (
  SELECT MAX(rulings_count) FROM (
    SELECT COUNT(*) AS rulings_count FROM rulings GROUP BY uuid
  ) AS counts
);

